-- SYNTHETIC ONLY: legacy Production schema shapes, 2 invented user IDs and invented RM transactions.
-- NEVER APPLY TO A REAL DATABASE. For disposable GitHub runner local Postgres only.
CREATE TABLE public.records (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at timestamptz NOT NULL DEFAULT now(),
  user_id uuid REFERENCES auth.users(id),
  type text,amount numeric,category text,method text,note text,date text
);
CREATE INDEX records_user_id_idx ON public.records(user_id);
CREATE TABLE public.transfers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  from_method text NOT NULL,to_method text NOT NULL,
  amount numeric NOT NULL CHECK(amount>0),note text DEFAULT ''::text,
  date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT transfers_different_methods CHECK(from_method<>to_method)
);
CREATE INDEX transfers_user_id_idx ON public.transfers(user_id);
CREATE TABLE public.user_settings (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  category_budgets jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  custom_options jsonb DEFAULT '{"incomeMethods":[],"expenseMethods":[],"incomeCategories":[],"expenseCategories":[]}'::jsonb
);
ALTER TABLE public.records ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.transfers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_settings ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.records,public.transfers,public.user_settings TO authenticated;
GRANT USAGE,SELECT ON SEQUENCE public.records_id_seq TO authenticated;
CREATE POLICY "Users can view own records" ON public.records FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users can insert own records" ON public.records FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can update own records" ON public.records FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can delete own records" ON public.records FOR DELETE TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users can view own transfers" ON public.transfers FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users can insert own transfers" ON public.transfers FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can update own transfers" ON public.transfers FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can delete own transfers" ON public.transfers FOR DELETE TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users can view own settings" ON public.user_settings FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY "Users can insert own settings" ON public.user_settings FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can update own settings" ON public.user_settings FOR UPDATE TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Users can delete own settings" ON public.user_settings FOR DELETE TO authenticated USING(auth.uid()=user_id);
